function makeGlowSprite(size = 64) {
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const g = c.getContext("2d")!;
  const grad = g.createRadialGradient(
    size / 2,
    size / 2,
    0,
    size / 2,
    size / 2,
    size / 2,
  );
  grad.addColorStop(0, "rgba(255,255,255,1)");
  grad.addColorStop(0.4, "rgba(255,255,255,0.35)");
  grad.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grad;
  g.fillRect(0, 0, size, size);
  return c;
}

export default function Preloader({
  assets = [],
  onEnter,
  onExitStart,
}: PreloaderProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const pathRef = useRef<SVGPathElement>(null);
  const starRefs = useRef<(HTMLDivElement | null)[]>([]);
  const startRef = useRef(performance.now());
  const enteredRef = useRef(false);
  const exitRef = useRef(false);
  const progressRef = useRef(assets.length === 0 ? 1 : 0);
  const [assetProgress, setAssetProgress] = useState(
    assets.length === 0 ? 1 : 0,
  );
  const [exiting, setExiting] = useState(false);

  useEffect(() => {
    startRef.current = performance.now();
    if (!assets.length) {
      progressRef.current = 1;
      setAssetProgress(1);
      return;
    }
    let cancelled = false,
      loaded = 0;
    const mark = () => {
      loaded++;
      if (!cancelled) {
        const p = loaded / assets.length;
        progressRef.current = p;
        setAssetProgress(p);
      }
    };
    Promise.all(
      assets.map(
        (src) =>
          new Promise<void>((resolve) => {
            const img = new Image();
            img.onload = () => {
              mark();
              resolve();
            };
            img.onerror = () => {
              mark();
              resolve();
            };
            img.src = src;
          }),
      ),
    ).then(() => {
      if (!cancelled) {
        progressRef.current = 1;
        setAssetProgress(1);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [assets.join("|")]);

  useEffect(() => {
    const canvas = canvasRef.current,
      path = pathRef.current;
    if (!canvas || !path) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    let width = 0,
      height = 0,
      frame = 0,
      dead = false;
    let logoDots: LogoDot[] = [];
    let backgroundStars: BackgroundStar[] = [];
    let shootingStars: ShootingStar[] = [];
    const glowSprite = makeGlowSprite(64);
    let lastFrameTime = performance.now();
    let virtualElapsed = 0;
    let resizeTimer: number | null = null;

    const ease = (v: number) => v * v * (3 - 2 * v);
    const sample = () => {
  const len = path.getTotalLength();
  const out: Point[] = [];

  const starCount =
    window.innerWidth <= 650
      ? MOBILE_PATH_STAR_COUNT
      : PATH_STAR_COUNT;

  for (let i = 0; i < starCount; i++) {
    const p = path.getPointAtLength(
      (len * i) / (starCount - 1)
    );

    out.push({
      x: p.x,
      y: p.y,
    });
  }

  return out;
};
    const screen = (p: Point): Point => {
      const scale = Math.min(
        (width * 0.96) / SVG_VIEWBOX_WIDTH,
        (height * 0.72) / SVG_VIEWBOX_HEIGHT,
      );
      const s = Math.max(0.2, scale);
      return {
        x: (width - SVG_VIEWBOX_WIDTH * s) / 2 + p.x * s,
        y: (height - SVG_VIEWBOX_HEIGHT * s) / 2 + p.y * s,
      };
    };
    const makeBackground = () => {
      backgroundStars = [];
      const layer = (
        count: number,
        depth: number,
        minSize: number,
        maxSize: number,
        minOpacity: number,
        maxOpacity: number,
        minSpeed: number,
        maxSpeed: number,
      ) => {
        for (let i = 0; i < count; i++)
          backgroundStars.push({
            x: Math.random() * width,
            y: Math.random() * height,
            size: minSize + Math.random() * (maxSize - minSize),
            opacity: minOpacity + Math.random() * (maxOpacity - minOpacity),
            depth,
            speed: minSpeed + Math.random() * (maxSpeed - minSpeed),
            phase: Math.random() * Math.PI * 2,
            twinkleSpeed: 0.35 + Math.random() * 0.9,
          });
      };
      layer(FAR_STARS, 0.16, 0.18, 0.65, 0.055, 0.2, 1, 4);
      layer(MID_STARS, 0.45, 0.4, 1.15, 0.12, 0.38, 4, 9);
      layer(NEAR_STARS, 0.95, 0.75, 1.9, 0.24, 0.62, 9, 18);
    };
    const randomizeShootingStar = (
      star: ShootingStar,
      now: number,
      initial: boolean,
    ) => {
      const depthRoll = Math.random();
      let depth = 0;
      if (depthRoll > 0.76) depth = 2;
      else if (depthRoll > 0.34) depth = 1;

      const x = -350 + Math.random() * (width * 1.15 + 350);
      let y: number;
      const positionRoll = Math.random();
      if (positionRoll < (initial ? 0.58 : 0.55)) {
        y = -250 + Math.random() * (height * (initial ? 0.78 : 0.75));
      } else {
        y = height * (initial ? 0.28 : 0.25) + Math.random() * (height * (initial ? 0.82 : 0.8));
      }
      const angle = ((12 + Math.random() * 32) * Math.PI) / 180;

      let speed: number, length: number, size: number, opacity: number;
      if (depth === 0) {
        speed = 110 + Math.random() * 120;
        length = 35 + Math.random() * 100;
        size = 0.55 + Math.random() * 0.55;
        opacity = 0.2 + Math.random() * 0.28;
      } else if (depth === 1) {
        speed = 180 + Math.random() * 180;
        length = 60 + Math.random() * 160;
        size = 0.75 + Math.random() * 0.85;
        opacity = 0.4 + Math.random() * 0.35;
      } else {
        speed = 300 + Math.random() * 260;
        length = 100 + Math.random() * 240;
        size = 1.0 + Math.random() * 1.5;
        opacity = 0.7 + Math.random() * 0.3;
      }

      star.x = x;
      star.y = y;
      star.angle = angle;
      star.speed = speed;
      star.length = length;
      star.size = size;
      star.depth = depth;
      star.opacity = opacity;
      star.nextSpawn = initial
        ? 0
        : now + 10 + Math.random() * 650;
    };
    const makeShooting = () => {
      const now = performance.now();
      shootingStars = Array.from({ length: SHOOTING_STARS }, () => {
        const star = {} as ShootingStar;
        randomizeShootingStar(star, now, true);
        return star;
      });
    };
    const makeLogo = () => {
      logoDots = sample().map((p, i) => {
        const q = screen(p);
        return {
          x: q.x,
          y: q.y,
          size: 1.25 + Math.random() * 1.35,
          order: i / (PATH_STAR_COUNT - 1),
          phase: Math.random() * Math.PI * 2,
        };
      });
    };
    const rebuild = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      makeBackground();
      makeShooting();
      makeLogo();
    };
    const resize = () => {
      if (resizeTimer !== null) window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        resizeTimer = null;
        rebuild();
      }, RESIZE_DEBOUNCE);
    };
    const animate = (time: number) => {
      if (dead) return;

      const rawDt = time - lastFrameTime;
      lastFrameTime = time;
      const dt = Math.min(Math.max(rawDt, 0), MAX_FRAME_DT);
      virtualElapsed += dt;
      const elapsed = virtualElapsed;

      const assetP = progressRef.current,
        timeP = Math.min(1, elapsed / MIN_LOGO_TIME),
        logoP = Math.min(assetP, timeP);

      ctx.fillStyle = BG_COLOR;
      ctx.fillRect(0, 0, width, height);

      backgroundStars.forEach((star) => {
        let x =
            (star.x + (star.speed * star.depth * elapsed) / 1000) %
            (width + 40),
          y =
            (star.y + (star.speed * 0.28 * star.depth * elapsed) / 1000) %
            (height + 40);
        if (x < 0) x += width + 40;
        if (y < 0) y += height + 40;
        const tw =
            (Math.sin(elapsed * 0.001 * star.twinkleSpeed + star.phase) + 1) /
            2,
          op = star.opacity * (0.7 + tw * 0.3);

        if (star.depth > 0.75) {
          const glowSize = star.size * 10;
          ctx.globalAlpha = op * 0.5;
          ctx.drawImage(
            glowSprite,
            x - glowSize / 2,
            y - glowSize / 2,
            glowSize,
            glowSize,
          );
          ctx.globalAlpha = 1;
        }
        ctx.beginPath();
        ctx.arc(x, y, star.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${STAR_COLOR},${op})`;
        ctx.fill();
      });

      shootingStars.forEach((star, i) => {
        const el = starRefs.current[i];
        if (!el) return;

        if (time < star.nextSpawn) {
          el.style.opacity = "0";
          return;
        }

        star.x += Math.cos(star.angle) * star.speed * (dt / 1000);
        star.y += Math.sin(star.angle) * star.speed * (dt / 1000);

        const x = star.x;
        const y = star.y;

        if (x > width + 450 || y > height + 450 || x < -450 || y < -450) {
          randomizeShootingStar(star, time, false);
          el.style.opacity = "0";
          return;
        }

        const lengthScale = star.length / 140;
        const angleDeg = (star.angle * 180) / Math.PI;
        const trailHeight = Math.max(1.5, star.size * 2.2);
        const headSize = Math.max(7, star.size * 10);

        el.style.setProperty("--star-length", `${star.length}px`);
        el.style.setProperty("--star-height", `${trailHeight}px`);
        el.style.setProperty("--head-size", `${headSize}px`);
        el.style.setProperty("--star-glow", `${3 + star.size * 3}px`);
        el.style.setProperty("--star-opacity", String(star.opacity));

        el.style.zIndex = String(20 + star.depth * 10);
        el.style.opacity = String(star.opacity);
        el.style.transform =
          `translate3d(${x}px, ${y}px, 0) ` +
          `translate(-100%, -50%) ` +
          `rotate(${angleDeg}deg) ` +
          `scaleX(${lengthScale})`;
      });
      logoDots.forEach((dot) => {
        const local = ease(
            Math.min(1, Math.max(0, (logoP - dot.order) / 0.1)),
          ),
          pulse = 0.9 + 0.1 * ((Math.sin(elapsed * 0.002 + dot.phase) + 1) / 2),
          op = 0.035 + local * 0.965 * pulse,
          r = dot.size * (0.7 + local * 0.55);

        if (local > 0.02) {
          const glowSize = r * (4 + local * 4);
          ctx.globalAlpha = op * local * 0.6;
          ctx.drawImage(
            glowSprite,
            dot.x - glowSize / 2,
            dot.y - glowSize / 2,
            glowSize,
            glowSize,
          );
          ctx.globalAlpha = 1;
        }

        ctx.beginPath();
        ctx.arc(dot.x, dot.y, r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${LOGO_COLOR},${op})`;
        ctx.fill();
      });

      frame = requestAnimationFrame(animate);
    };

    window.addEventListener("resize", resize);
    rebuild();
    frame = requestAnimationFrame(animate);
    return () => {
      dead = true;
      window.removeEventListener("resize", resize);
      if (resizeTimer !== null) window.clearTimeout(resizeTimer);
      cancelAnimationFrame(frame);
    };
  }, []);

  useEffect(() => {
    const timer = window.setInterval(() => {
      if (
        !exitRef.current &&
        progressRef.current >= 1 &&
        performance.now() - startRef.current >= MIN_LOGO_TIME
      ) {
        exitRef.current = true;
        window.clearInterval(timer);
        window.setTimeout(() => {
          setExiting(true);
          onExitStart?.();
          window.setTimeout(() => {
            if (!enteredRef.current) {
              enteredRef.current = true;
              onEnter();
            }
          }, EXIT_DURATION);
        }, LOGO_HOLD);
      }
    }, 50);
    return () => window.clearInterval(timer);
  }, [onEnter, onExitStart]);

  return (
    <div
      className={[styles.preloader, exiting ? styles.exiting : ""].join(" ")}
      style={{ "--exit-duration": `${EXIT_DURATION}ms` } as React.CSSProperties}
    >
      <canvas ref={canvasRef} className={styles.canvas} />
      <svg
        className={styles.sourceSvg}
        viewBox={`0 0 ${SVG_VIEWBOX_WIDTH} ${SVG_VIEWBOX_HEIGHT}`}
        preserveAspectRatio="xMidYMid meet"
        aria-hidden="true"
      >
        <path ref={pathRef} d={PATH_D} />
      </svg>
      <div className={styles.shootingStars}>
        {Array.from({ length: SHOOTING_STARS }).map((_, i) => (
          <div
            key={i}
            ref={(el) => {
              starRefs.current[i] = el;
            }}
            className={styles.star}
            style={{
              opacity: 0,
              zIndex: 20,
              willChange: "transform, opacity",
              left: 0,
              top: 0,
            }}
          />
        ))}
      </div>
      <div className={styles.loadingBarRow}>
        <span className={styles.loadingBarPercent}>
          {Math.round(assetProgress * 100)}%
        </span>
        <div className={styles.loadingBar}>
          <div
            className={styles.loadingBarFill}
            style={{ width: `${assetProgress * 100}%` }}
          />
        </div>
      </div>
      <div className={styles.vignette} />
    </div>
  );
}